                />
            </View>
        ),
        [styles, importCustomField, translate],
    );

    return (
        <ConnectionLayout
            displayName={NetSuiteImportCustomFieldPage.displayName}
            headerTitle={`workspace.netsuite.import.importCustomFields.${importCustomField}.title`}
